import { createSlice } from '@reduxjs/toolkit';
import uuid from 'uuid/v4';

const initialState = [];

const cartContentsSlice = createSlice({
  name: 'cartContents',
  initialState,
  reducers: {
    addToCart: (state, action) => {
      const newItem = { ...action.payload, id: uuid() };
      return [...state, newItem];
    },
    removeFromCart: (state, action) => {
      return state.filter(item => item.id !== action.payload);
    },
    increaseQuantity: (state, action) => {
      const index = state.findIndex(item => item.id === action.payload);
      if (index !== -1) {
        return [...state.slice(0, index), { ...state[index], quantity: state[index].quantity + 1 }, ...state.slice(index + 1)];
      }
      return state;
    },
    decreaseQuantity: (state, action) => {
      const index = state.findIndex(item => item.id === action.payload);
      if (index !== -1 && state[index].quantity > 1) {
        return [...state.slice(0, index), { ...state[index], quantity: state[index].quantity - 1 }, ...state.slice(index + 1)];
      }
      if (index !== -1 && state[index].quantity === 1) {
        return [...state.slice(0, index), ...state.slice(index + 1)];
      }
      return state;
    }}});

export const { addToCart, removeFromCart, increaseQuantity, decreaseQuantity } = cartContentsSlice.actions;
export default cartContentsSlice.reducer;

